/**
 * WHY duplicate-character logic lives here:
 * Per PRD §5.4: duplicating a character creates a new record with the same
 * attributes, skills, conditions, and inventory but:
 *   - new id (generated by Prisma)
 *   - name becomes "<original> (copy)"
 *   - experience is zeroed (new character starts fresh XP-wise)
 *   - hpCurrent / mpCurrent reset to the derived-stat placeholders
 *
 * Items, talents, relationships, and critical injuries are deep-copied by
 * the repo implementation (new rows with new ids).
 */
import { Inject } from '@nestjs/common';
import { CommandHandler, EventBus, ICommandHandler } from '@nestjs/cqrs';

import { CharacterNotFoundError, CharacterNotOwnedError } from '../domain/character.errors';
import { CHARACTER_REPO, CharacterReadModel } from '../domain/character.ports';
import { CharacterUpdatedEvent } from '../events/character-updated.event';

import { DuplicateCharacterCommand } from './duplicate-character.command';

import type { ICharacterRepo } from '../domain/character.ports';

@CommandHandler(DuplicateCharacterCommand)
export class DuplicateCharacterHandler implements ICommandHandler<
  DuplicateCharacterCommand,
  CharacterReadModel
> {
  constructor(
    @Inject(CHARACTER_REPO) private readonly repo: ICharacterRepo,
    private readonly eventBus: EventBus,
  ) {}

  async execute(command: DuplicateCharacterCommand): Promise<CharacterReadModel> {
    const { characterId, ownerId } = command;

    const source = await this.repo.findActiveById(characterId);
    if (!source) throw new CharacterNotFoundError(characterId);
    if (source.ownerId !== ownerId) throw new CharacterNotOwnedError(characterId);

    const copy = await this.repo.create({
      ownerId,
      name: `${source.name} (copy)`,
      concept: source.concept,
      iconId: source.iconId,
      upbringing: source.upbringing,
      origin: source.origin,
      reputation: source.reputation,
      startingWealth: source.startingWealth,
      // Wallet starts in lockstep with the historical record on the new
      // copy too — duplicating a character resets the wallet to its
      // canonical starting balance rather than carrying over the source
      // character's spent / earned birrs.
      birr: source.startingWealth,
      crewConcept: source.crewConcept,
      mutant: source.mutant,
      mutantLineage: source.mutantLineage,
      attributes: source.attributes,
      skills: source.skills,
      // TODO(rules-engine, T-3.2.2): replace constants with computeHpMax / computeMpMax
      hpCurrent: 14,
      mpCurrent: 10,
      experience: 0,
      conditions: source.conditions,
      notes: source.notes,
    });

    this.eventBus.publish(new CharacterUpdatedEvent(copy.id, copy.ownerId));

    return copy;
  }
}
